PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE, last_seen INTEGER NOT NULL);
CREATE TABLE sessions(hash TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires);
CREATE TABLE edges(a TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,b TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,requester TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','accepted')),created INTEGER NOT NULL,PRIMARY KEY(a,b),CHECK(a<b));
CREATE INDEX edges_b ON edges(b);
CREATE TABLE blocks(owner TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,target TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(owner,target));
CREATE TABLE messages(id INTEGER PRIMARY KEY AUTOINCREMENT,sender TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,recipient TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 2000),created INTEGER NOT NULL);
CREATE INDEX messages_conversation ON messages(sender,recipient,id);
CREATE INDEX messages_expiry ON messages(created);
CREATE TABLE limits(key TEXT PRIMARY KEY,window INTEGER NOT NULL,count INTEGER NOT NULL);
